package org.overengineer.bettacraft.genetics;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Named betta colours (tints for the greyscale masks). The table is generated by tools/assetgen/palette.py
 * ({@link BettaColorTable}); M5 makes it datapack-driven ({@code data/bettacraft/bettacraft/colors}).
 */
public final class BettaColors {
    /** Neutral grey for unknown (e.g. removed datapack) colour ids. */
    public static final int FALLBACK_RGB = 0x9A9A9A;
    private static final Map<String, Integer> RGB = new HashMap<>();
    private static final List<String> IDS;

    static {
        for (BettaColorTable.Entry e : BettaColorTable.COLORS) RGB.put(e.id(), e.rgb());
        IDS = BettaColorTable.COLORS.stream().map(BettaColorTable.Entry::id).toList();
    }

    private BettaColors() {}

    public static List<String> ids() {
        return IDS;
    }

    public static List<String> iridescentIds() {
        return BettaColorTable.IRIDESCENT;
    }

    public static boolean isKnown(String id) {
        return RGB.containsKey(id);
    }

    public static int rgb(String id) {
        return RGB.getOrDefault(id, FALLBACK_RGB);
    }

    public static String translationKey(String id) {
        return "color.bettacraft." + id;
    }
}
